{
  "schemaVersion": "0.2",
  "slug": "chat-bubble",
  "name": "ChatBubble",
  "family": "H",
  "status": "experimental",
  "purpose": "Presents a single chat message aligned and styled by its author role.",
  "scenarios": [
    "User prompt in an AI chat",
    "Assistant answer with markdown body",
    "System notice between turns"
  ],
  "props": {
    "role": {
      "type": "enum",
      "required": false,
      "description": "Author role driving alignment and tone.",
      "values": [
        "user",
        "assistant",
        "system"
      ],
      "default": "assistant"
    },
    "children": {
      "type": "node",
      "required": true,
      "description": "Message body content."
    },
    "time": {
      "type": "string",
      "required": false,
      "description": "Timestamp text."
    },
    "label": {
      "type": "string",
      "required": false,
      "description": "Accessible label override."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "role",
      "values": [
        "user",
        "assistant",
        "system"
      ],
      "default": "assistant",
      "description": "Author role."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Message bubble rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "card",
      "app-shell"
    ],
    "allowedChildren": [
      "markdown-renderer",
      "text",
      "code-block"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use a chat bubble outside conversational UI.",
    "Do not place interactive forms inside a system bubble."
  ],
  "a11y": {
    "role": "article",
    "keyboard": [],
    "focus": "Interactive children keep document order.",
    "labeling": "Author role is exposed as text for screen readers.",
    "wcag": [
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Bubble max measure shrinks on compact.",
    "breakpoints": {
      "compact": "Near full width.",
      "medium": "Constrained measure.",
      "large": "Constrained measure."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "chat-bubble",
    "states": [
      "default",
      "user",
      "assistant",
      "system"
    ],
    "intents": [
      "notify-status"
    ]
  }
}

.cu-chat-bubble {
  display: flex;
  gap: var(--cu-space-2);
  max-inline-size: 36rem;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border-radius: var(--cu-radius-md);
  color: var(--cu-color-fg-default);
  background: color-mix(in srgb, var(--cu-color-palette-brand) 8%, var(--cu-color-background-default));
}

.cu-chat-bubble--user {
  margin-inline-start: auto;
  background: var(--cu-color-palette-brand);
  color: var(--cu-color-fg-inverse);
}

.cu-chat-bubble--system {
  background: transparent;
  border: 1px dashed var(--cu-color-border-default);
}

.cu-chat-bubble--error {
  border: 1px solid var(--cu-color-palette-brand);
}

.cu-chat-bubble__avatar {
  inline-size: var(--cu-space-3);
  block-size: var(--cu-space-3);
  border-radius: 50%;
  flex-shrink: 0;
}

.cu-chat-bubble__content {
  min-inline-size: 0;
}

.cu-chat-bubble__meta {
  display: flex;
  gap: var(--cu-space-2);
  font-size: 0.75em;
  opacity: 0.8;
}

.cu-chat-bubble__role {
  font-weight: 600;
  text-transform: capitalize;
}

.cu-chat-bubble__status {
  font-style: italic;
}

.cu-chat-bubble--streaming .cu-chat-bubble__status {
  animation: cu-chat-bubble-pulse 1.2s ease-in-out infinite;
}

.cu-chat-bubble__body {
  margin-block-start: var(--cu-space-1);
}

@keyframes cu-chat-bubble-pulse {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}
